["Constructor"] = "function (self, unitId, unitFrame, envTable)\n    envTable.color = \"#5d00ff\"\n    \n    envTable.npcs = {\n        [61056] = \"Greater Earth Elemental\",\n        [61146] = \"Black Ox Statue\",\n        [95072] = \"Earth Elemental\",\n        [103822] = \"Treant\"\n    }\n    \n    envTable.rules = {\n        [\"Pet\"] = true,\n        [\"Creature\"] = function(npcID)\n            return (envTable.npcs[npcID] ~= nil)\n        end\n    }\n    \n    envTable.getTypeAndID = function(guid)\n        local unitType, _, _, _, _, npcID = strsplit(\"-\", guid)\n        return unitType, tonumber(npcID or \"0\") or 0\n    end\n    \n    envTable.shallHighlight = function(self, guid)\n        local unitType, npcID = envTable.getTypeAndID(guid)\n        \n        if not unitType then\n            return false\n        end\n        \n        local value = envTable.rules[unitType]\n        \n        if value == nil then\n            return false\n        end\n        \n        \n        if type(value) == \"boolean\" then\n            return value\n        end\n        \n        if type(value) == \"function\" then\n            return value(npcID)\n        end\n        \n        return false\n    end\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["Nameplate Updated"] = "function (self, unitId, unitFrame, envTable)    \n    if not self.InCombat then\n        return\n    end\n    \n    if self.namePlateThreatIsTanking then\n        return\n    end\n    \n    if UnitIsTapDenied(unitId) then\n        return\n    end\n    \n    local exists = UnitExists(self.targetUnitID)\n    \n    if not exists then\n        return\n    end\n    \n    local role = UnitGroupRolesAssigned(self.targetUnitID)\n    local isTank = role == \"TANK\"\n    \n    if isTank then\n        return\n    end\n    \n    \n    local guid = UnitGUID(self.targetUnitID)\n    \n    if envTable.shallHighlight(self, guid) then\n        Plater.SetNameplateColor(unitFrame, envTable.color)\n    end   \nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
},
