["Health Update"] = "function (self, unitId, unitFrame, envTable, modTable)\n    --insert code here\n    envTable.UpdateHealth (unitFrame)\nend\n\n\n",
["Nameplate Updated"] = "function (self, unitId, unitFrame, envTable, modTable)\n    --insert code here\n    envTable.UpdateHealth (unitFrame)\nend\n\n\n",
["Constructor"] = "function (self, unitId, unitFrame, envTable, modTable)\n    \n    envTable.Fengefu = \" - \" --分隔符\n    \n    function envTable.UpdateHealth (unitFrame)\n        --获取当前血量\n        local currentHealth = unitFrame.healthBar.CurrentHealth or 0\n        local healthString = Plater.FormatNumber (currentHealth) .. \"\"\n        local currentHealthMax = unitFrame.healthBar.CurrentHealthMax or 0\n        local percent = currentHealth / currentHealthMax * 100\n        local xiaoshudian = \"%.1f\"\n        \n        if (percent == 100) then\n            xiaoshudian = \"%.0f\"\n        elseif (percent < 10) then\n            xiaoshudian = \"%.2f\"\n        end   \n        \n        healthString = healthString .. envTable.Fengefu .. format (xiaoshudian, percent) .. \"%\"\n        \n        --设置文本\n        unitFrame.healthBar.lifePercent:SetText (healthString)\n    end\nend\n\n\n",
},
